import csv
import io
import re
from typing import Any, List, Dict


def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = ","
    quotechar = '"'

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=delimiter,
        quotechar=quotechar,
        doublequote=True,
        strict=False,
    )

    records = []
    try:
        for record in reader:
            if record and any(value != "" for value in record):
                records.append(record)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    identifier_re = re.compile(r"^[A-Za-z_][A-Za-z0-9_ \-./]*$")
    date_re = re.compile(
        r"^(?:\d{1,4}[/\-]\d{1,2}[/\-]\d{1,4}|\d{1,2}:\d{2}(?::\d{2})?)$"
    )
    number_re = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$")

    def header_score(record: List[str]) -> int:
        if len(record) != expected_width:
            return -1000
        score = 0
        for value in record:
            text = value.strip()
            if text and identifier_re.fullmatch(text):
                score += 2
            elif text:
                score -= 1
        first = record[0].strip() if record else ""
        if first and not date_re.fullmatch(first) and not number_re.fullmatch(first):
            score += 3
        if first and identifier_re.fullmatch(first):
            score += 3
        return score

    header_index = 0
    best_score = -1001
    for index, record in enumerate(records):
        score = header_score(record)
        if score > best_score:
            best_score = score
            header_index = index

    def normalize(record: List[str]) -> List[str]:
        if len(record) == expected_width:
            return list(record)
        if len(record) < expected_width:
            return list(record) + [""] * (expected_width - len(record))
        return list(record[: expected_width - 1]) + [delimiter.join(record[expected_width - 1 :])]

    columns = normalize(records[header_index])
    columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    normalized_header = columns
    for record in records[header_index + 1 :]:
        row = normalize(record)
        if row == normalized_header:
            continue
        rows.append(row)

    return {"columns": columns, "rows": rows}
